    this.lrc,
    this.plain,
    this.writeBack = false,
    this.lock = true,
    this.force = false,
  });

  /// Timed lines as LRC text. Malformed lines are skipped and reported as
  /// warnings with their line numbers.
  final String? lrc;

  /// A plain unsynchronized block.
  final String? plain;

  /// Write the `.lrc` sidecar next to the file and embed where the format
  /// allows.
  final bool writeBack;

  /// Lock the lyrics artifact.
  final bool lock;

  /// Override an existing lock.
  final bool force;
}

/// The stored lyrics, when any.
class LyricsState {
  const LyricsState({
    required this.synced,
    required this.source,
    this.provider,
    this.lrc,
  });

  /// Whether timed lines are stored.
  final bool synced;

  /// Where the stored copy came from: `tag` (an embedded USLT/SYLT frame),
  /// `sidecar` (an `.lrc` beside the audio), `user`, or `enrichment`. A string,
  /// not a closed enum.
  ///
  /// This is the same vocabulary artwork reports, so one mark serves both. It
  /// replaces the older `lrc`/`embedded` pair, which named the two file formats
  /// rather than the producer and had nowhere to put a fetched copy; `lrc` is
  /// now `sidecar` and `embedded` is now `tag`.
  final String source;

  /// The lyrics provider that supplied an `enrichment` copy. Empty for every
  /// other source.
  final String? provider;

  /// The lyrics serialized as LRC text (timed lines when synced, bare lines
  /// otherwise), the editor's working format.
  final String? lrc;
}

/// The staged parts of one item's editor draft. Every part is optional and at
/// least one is required; an empty body answers `invalid-request` rather than
/// committing nothing successfully.
///
/// The three write switches are hoisted out of the per-part bodies the
/// sequential endpoints take, because a draft is saved with one set of them.
class MetadataCommit {
  const MetadataCommit({
    this.fields,
    this.credits = const [],
    this.lyrics,
    this.clearLyrics = false,
    this.chapters,
    this.tagSets = const {},
    this.tagRemoves = const [],
    this.unofficial,
    this.writeBack = false,
    this.lock = true,
    this.force = false,
  });

  /// Field name to new value; an empty string clears the field. Names come from
  /// the kind's vocabulary, as for `editItemMetadata`.
  final Map<String, String>? fields;

  /// Replacement people per role. They apply as one atomic batch, which is what
  /// lets an artist every listed role moves be renamed in place rather than
  /// left behind; a role named twice answers `invalid-request`. Because the
  /// batch is atomic, a refusal in any role leaves them all uncommitted: the
  /// first `credit` part carries the refusal and the rest read `skipped`, and
  /// the message names the role that refused.
  final List<CommitCredits> credits;

  final CommitLyrics? lyrics;

  /// Remove the stored lyrics. Mutually exclusive with `lyrics`; sending both
  /// answers `invalid-request`.
  final bool clearLyrics;

  /// A replacement chapter list for a book: ordered, non-overlapping, on the
  /// book timeline. An empty array restores the embedded chapters, as for
  /// `setBookChapters`.
  final List<ChapterMark>? chapters;

  /// Custom tag key to its replacement values; empty values clear that tag.
  /// Applied in sorted key order, because a JSON object carries none of its own
  /// and the parts list has to be reproducible.
  final Map<String, List<String>> tagSets;

  /// Custom tag keys to remove, applied in the order given.
  final List<String> tagRemoves;

  /// The release-status mark: true marks the item as having no canonical
  /// release, false clears the mark. Omitted leaves it alone.
  final bool? unofficial;

  /// Also write the new values into the backing file's tags, for the parts that
  /// have a tag form (fields, credits, lyrics, custom tags, the release
  /// status), and removes a cleared lyrics sheet's `.lrc` sidecar.
  final bool writeBack;

  /// Lock what each part wrote, against scans and enrichment.
  final bool lock;

  /// Override existing locks.
  final bool force;
}

/// One part of a compound commit and what became of it.
class MetadataCommitPart {
  const MetadataCommitPart({
    required this.part,
    required this.status,
    this.detail,
    this.refusal,
  });

  /// Which staged part this entry is about. `lyrics` covers both replacing them
  /// and clearing them.
  final MetadataCommitPartKind part;

  /// Which one, where the part repeats: the role for `credit`, the tag key for
  /// `tagSet` and `tagRemove`. Absent otherwise.
  final String? detail;

  /// `committed` means the catalog write landed (write-back trouble rides
  /// `writeBackFailures`, never this). `refused` is the one part that stopped
  /// the commit, with its `refusal`. `skipped` is a part after that one, which
  /// was never attempted, or a `credit` role that shared an atomic batch with
  /// the refused one.
  final MetadataCommitStatus status;

  final WaxDeckApiException? refusal;
}

/// What a compound commit did, part by part in execution order.
///
/// Read `parts` rather than the status code: a refusal is a 200 here, and the
/// accumulated `writeBackFailures` and `warnings` belong to the parts that
/// committed before it.
///
/// There is no `resultingAlbumPid`. Editing a release-keying field on one item
/// can still regroup its release, exactly as `editItemMetadata` can, and
/// neither operation reports where it landed; only the bulk edit does, because
/// only its caller (the release workbench) is following a whole release across
/// the move.
class MetadataCommitResult {
  const MetadataCommitResult({
    required this.parts,
    this.writeBackFailures = const [],
    this.warnings = const [],
  });

  /// One entry per part the request carried, in the order they were run. A part
  /// after a refused one is present and `skipped`, so the list always accounts
  /// for the whole request.
  final List<MetadataCommitPart> parts;

  /// Files whose tags could not be updated, merged across every part and
  /// deduplicated: several parts can report the same file for the same reason,
  /// and each line is for a person to read once.
  final List<WriteBackFailure> writeBackFailures;

  /// The parts' non-fatal notes, merged: typed drop warnings from the tag
  /// library, roles without a tag form, malformed LRC lines skipped.
  final List<String> warnings;
}

/// Scalar field edits for one item.
class MetadataEdit {
  const MetadataEdit({
    required this.fields,
    this.writeBack = false,
    this.lock = true,
    this.force = false,
  });

  /// Field name to new value; an empty string clears the field. Names come from
  /// the kind's vocabulary.
  final Map<String, String> fields;

  /// Also write the new values into the file's tags.
  final bool writeBack;

  /// Lock the edited fields.
  final bool lock;

  /// Override existing locks on the edited fields.
  final bool force;
}

/// The outcome of a metadata mutation. The catalog write succeeded whenever
/// this shape returns; write-back trouble and drop warnings ride along instead
/// of failing the edit.
class MetadataEditResult {
  const MetadataEditResult({
    required this.applied,
    this.writeBackFailures = const [],
    this.warnings = const [],
    this.mergedInto,
    this.movedAlbums = const [],
  });

  /// Always true; the catalog committed.
  final bool applied;

  /// Files whose tags could not be updated.
  final List<WriteBackFailure> writeBackFailures;

  /// Non-fatal notes: typed drop warnings from the tag library (a format
  /// refusing embedded synced lyrics, a chapter cap), roles without a tag form,
  /// malformed LRC lines skipped.
  final List<String> warnings;

  /// The surviving entity when the edit re-keyed this one onto a key another
  /// entity already held, which only an `mbid` clear does. The named entity is
  /// gone; talk about this pid instead.
  final String? mergedInto;

  /// Albums that left the edited release group because the clear re-keyed it
  /// and their titles put them in a group of their own. Their members are no
  /// longer reachable through the edited group.
  final List<String> movedAlbums;
}

/// The editor's field vocabulary.
class MetadataFields {
  const MetadataFields({
    required this.kinds,
    required this.entityTypes,
    this.reservedTagKeys = const [],
  });

  /// Editable fields per item kind.
  final List<KindFields> kinds;

  /// Editable fields per entity type.
  final List<EntityTypeFields> entityTypes;

  /// Custom-tag keys the catalog owns through a field of its own (`BPM` through
  /// `bpm`, `ISRC` through `isrc`, and so on), in sorted order. A custom-tag
  /// editor refuses one of these before the round trip; `setItemTag` refuses it
  /// either way.
  final List<String> reservedTagKeys;
}

/// The unofficial mark.
class ReleaseStatusEdit {
  const ReleaseStatusEdit({required this.unofficial, this.writeBack = false});

  /// True marks the item as having no canonical release; false clears the mark.
  final bool unofficial;

  /// Also write the mark into (or strip it from) the item's files'
  /// `RELEASESTATUS` tag.
  final bool writeBack;
}

/// The review entry a rematch opened.
class RematchResult {
  const RematchResult({required this.reviewEntryId});

  /// The pending entry; candidates fill in asynchronously.
  final String reviewEntryId;
}

/// The items to change, and what they become.
class SetItemKindRequest {
  const SetItemKindRequest({
    required this.pids,
    required this.mediaType,
    this.writeBack = false,
  });

  /// The items, by pid. Tracks named together whose tags name one book become
  /// that book.
  final List<String> pids;

  /// What the items become.
  final String mediaType;

  /// Also write the kind into the files. A book gets the audiobook media type,
  /// which even a scan that re-derives everything reads back as a book; a track
  /// has it cleared, so such a scan reads it as music only where nothing else
  /// marks it a book (an `.m4b` name, a narrator, the Audiobook genre, a
  /// library that holds Books). Without it the catalog's pin alone keeps the
  /// choice. A file that cannot be written is listed in the job result's
  /// `writeBackFailures` and the change stands.
  final bool writeBack;
}

/// Replacement values for one custom tag.
class TagEdit {
  const TagEdit({
    required this.values,
    this.lock = true,
    this.force = false,
    this.writeBack = false,
  });

  /// Ordered values; empty clears the tag.
  final List<String> values;

  /// Lock `tag.KEY`.
  final bool lock;

  /// Override an existing lock.
  final bool force;

  /// Also write the values into the item's files.
  final bool writeBack;
}

/// The outcome of a tag edit.
class TagEditResult {
  const TagEditResult({
    required this.key,
    required this.stored,
    this.writeBackFailures = const [],
  });

  /// The canonical uppercase key actually used.
  final String key;

  /// Values stored after deduplication.
  final int stored;

  /// Files the write-back could not update; the catalog edit stands. Absent
  /// when every file took the values or no write-back was asked for.
  final List<WriteBackFailure> writeBackFailures;
}

/// One file a write-back could not update. A caller who is not an administrator
/// is told only of files in libraries they are granted.
class WriteBackFailure {
  const WriteBackFailure({
    required this.filePid,
    required this.reason,
    this.path,
  });

  /// The file; empty for a failure no one file caused.
  final String filePid;

  /// Its display path, or its file name for a caller who is not an
  /// administrator.
  final String? path;

  /// Why the write failed or was refused, without the server's paths for a
  /// caller who is not an administrator.
  final String reason;
}

/// One file out of step with the catalog.
class WriteBackIssue {
  const WriteBackIssue({
    required this.filePid,
    required this.code,
    this.tagKey,
    this.detail,
  });

  /// The backing file.
  final String filePid;

  /// The diagnostic: `tag-write-unsynced` (a write-back was refused or failed;
  /// the file's tags lag the catalog), `tag-write-lost` (the write ran but the
  /// format could not store the value), or `tag-write-owed` (an edit changed
  /// the value in the catalog without writing it; `tagKey` names it). A string,
  /// not a closed enum.
  final String code;

  /// The affected key, when known. On a `tag-write-owed` issue it is the
  /// catalog's name for the value: an item field (`title`), a credit
  /// (`credit.composer`), a custom tag (`tag.MOOD`), the item's front cover
  /// (`art`) or origin (`acquisition`), or an entity value written to member
  /// files (`album.label`, `album.art`).
  final String? tagKey;

  /// Human-readable detail, administrators only. It is the tag writer's own
  /// error, which names the file's absolute path, so it is withheld from
  /// everyone else exactly as the diagnostics listing is; `code`, `tagKey`, and
  /// `filePid` say what went wrong without saying where the library lives.
  /// Absent rather than redacted for a non-administrator.
  final String? detail;
}
